div.script:

const allTeams = ["KC", "BUF", "PHI", "SF", "BAL", "DET", "DAL", "CIN", "MIA", "GB", "NYJ", "LAC", "CHI", "MIN", "SEA", "TB"];

const rosterSchema = [
  { pos: "QB", era: "Any Era", tagClass: "era-any" },
  { pos: "RB", era: "2010+", tagClass: "era-modern" },
  { pos: "WR1", era: "1995-2009", tagClass: "era-bridge" },
  { pos: "WR2", era: "Any Era", tagClass: "era-any" },
  { pos: "TE", era: "Any Era", tagClass: "era-any" },
  { pos: "DL", era: "Pre-1995", tagClass: "era-classic" },
  { pos: "LB", era: "Any Era", tagClass: "era-any" },
  { pos: "DB", era: "2010+", tagClass: "era-modern" }
];

let chosenFranchise = "";
let dealtTeams = [];
let currentPickIndex = 0;
let userRoster = {};
let bestRecord = localStorage.getItem('per36_17_0_best') || 0;

document.getElementById('bestRecordDisplay').textContent = `Best Wins: ${bestRecord}/17`;

// Render franchise pick options
const picker = document.getElementById('teamPicker');
allTeams.forEach(t => {
  const chip = document.createElement('div');
  chip.className = 'team-chip';
  chip.textContent = t;
  chip.onclick = () => selectFranchise(t);
  picker.appendChild(chip);
});

function selectFranchise(team) {
  chosenFranchise = team;

  const remaining = allTeams.filter(t => t !== team);
  const shuffled = remaining.sort(() => 0.5 - Math.random());
  dealtTeams = [team, ...shuffled.slice(0, 7)];

  document.getElementById('stepTeam').style.display = 'none';
  document.getElementById('stepDraft').style.display = 'block';

  updateDraftPrompt();
}

function updateSlotDropdown() {
  const select = document.getElementById('slotSelector');
  select.innerHTML = '';
  rosterSchema.forEach((slot) => {
    if (!userRoster[slot.pos]) {
      const opt = document.createElement('option');
      opt.value = slot.pos;
      opt.textContent = `${slot.pos} (${slot.era})`;
      select.appendChild(opt);
    }
  });
}

function renderRosterState() {
  const container = document.getElementById('rosterContainer');
  container.innerHTML = '';

  rosterSchema.forEach((slot) => {
    const row = document.createElement('div');
    row.className = 'roster-row';
    const filled = userRoster[slot.pos];
    const textDisplay = filled ? `<b>${filled.player}</b> (${filled.team})` : '<i>Empty Slot</i>';

    row.innerHTML = `
      <div style="display:flex; align-items:center;">
        <span class="pos-badge">${slot.pos}</span>
        <span class="era-tag ${slot.tagClass}">${slot.era}</span>
      </div>
      <span class="player-name" style="color:${filled ? '#f8fafc':'#64748b'}">${textDisplay}</span>
    `;
    container.appendChild(row);
  });
}

function updateDraftPrompt() {
  if (currentPickIndex < 8) {
    document.getElementById('currentPickNum').textContent = currentPickIndex + 1;
    document.getElementById('dealtTeamTitle').textContent = `${dealtTeams[currentPickIndex]} Franchise`;
    document.getElementById('playerInput').value = '';
    updateSlotDropdown();
    renderRosterState();
  } else {
    runSeasonSimulation();
  }
}

function submitPlayer() {
  const val = document.getElementById('playerInput').value.trim();
  const targetSlot = document.getElementById('slotSelector').value;
  if (!val || !targetSlot) return;

  userRoster[targetSlot] = {
    player: val,
    team: dealtTeams[currentPickIndex]
  };

  currentPickIndex++;
  updateDraftPrompt();
}

function runSeasonSimulation() {
  document.getElementById('stepDraft').style.display = 'none';
  document.getElementById('stepResult').style.display = 'block';

  let wins = 0;
  let losses = 0;
  const badges = document.getElementById('scheduleBadges');
  badges.innerHTML = '';

  for (let i = 1; i <= 17; i++) {
    const isWin = Math.random() < 0.81;
    const badge = document.createElement('div');
    badge.className = `game-badge ${isWin ? 'win' : 'loss'}`;
    badge.textContent = isWin ? 'W' : 'L';
    badges.appendChild(badge);

    if (isWin) wins++; else losses++;
  }

  document.getElementById('recordOutput').textContent = `${wins}-${losses}`;
  document.getElementById('resultHeader').textContent = wins === 17 ? "🏆 PERFECT 17-0 SEASON!" : "Regular Season Finished";

  const playoffBox = document.getElementById('playoffOutput');
  if (wins >= 12) {
    playoffBox.style.display = 'block';
    if (wins === 17) {
      playoffBox.innerHTML = `🏆 <b>SUPER BOWL RUN:</b> Divisional: WIN | Conference: WIN | Super Bowl: CHAMPIONS!`;
    } else {
      playoffBox.innerHTML = `🏈 <b>PLAYOFF RUN:</b> Made playoffs as a wild card team!`;
    }
  } else {
    playoffBox.style.display = 'none';
  }

  if (wins > bestRecord) {
    bestRecord = wins;
    localStorage.setItem('per36_17_0_best', bestRecord);
    document.getElementById('bestRecordDisplay').textContent = `Best Wins: ${bestRecord}/17`;
  }
}

function resetGame() {
  currentPickIndex = 0;
  userRoster = {};
  document.getElementById('stepResult').style.display = 'none';
  document.getElementById('stepTeam').style.display = 'block';
}
